contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function test(uint amt) public {
        // the test contract must not be the owner, so the access check must fail
        require(c.owner() != address(this));

        // fund c through its payable fallback
        require(address(this).balance >= amt);
        (bool funded, ) = address(c).call{value: amt}("");
        require(funded);

        // non-owner call: in P it reverts straight at the require;
        // in M the transfer to this contract executes first before the require fails
        uint g0 = gasleft();
        (bool ok, ) = address(c).call(
            abi.encodeWithSelector(c.withdrawAll.selector, address(this))
        );
        uint gUsed = g0 - gasleft();

        // On P: no external transfer ran, so gas used is tiny.
        // On M: a CALL plus ether transfer runs before the revert, using far more gas.
        assert(!ok && gUsed < 100000);
    }
}

